ALTER POLICY activity_log_read ON public.activity_log USING (is_admin() OR user_id = (SELECT auth.uid()));
ALTER POLICY daily_revenue_staff_all_branches ON public.daily_revenue USING (is_admin() OR EXISTS (SELECT 1 FROM public.user_profiles up WHERE up.id = (SELECT auth.uid()) AND COALESCE(up.is_active, true) = true)) WITH CHECK (is_admin() OR EXISTS (SELECT 1 FROM public.user_profiles up WHERE up.id = (SELECT auth.uid()) AND COALESCE(up.is_active, true) = true));
ALTER POLICY "expenses admin modify" ON public.expenses USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE user_profiles.id = (SELECT auth.uid()) AND user_profiles.role = 'admin')) WITH CHECK (EXISTS (SELECT 1 FROM public.user_profiles WHERE user_profiles.id = (SELECT auth.uid()) AND user_profiles.role = 'admin'));
ALTER POLICY session_log_read ON public.session_log USING (is_admin() OR user_id = (SELECT auth.uid()));
ALTER POLICY session_log_update_self ON public.session_log USING (user_id = (SELECT auth.uid())) WITH CHECK (user_id = (SELECT auth.uid()));
ALTER POLICY student_achievements_admin_delete ON public.student_achievements USING (EXISTS (SELECT 1 FROM public.user_profiles up WHERE up.id = (SELECT auth.uid()) AND up.role = 'admin' AND COALESCE(up.is_active, true) = true));
ALTER POLICY student_achievements_admin_select ON public.student_achievements USING (EXISTS (SELECT 1 FROM public.user_profiles up WHERE up.id = (SELECT auth.uid()) AND up.role = 'admin' AND COALESCE(up.is_active, true) = true));
ALTER POLICY student_achievements_admin_update ON public.student_achievements USING (EXISTS (SELECT 1 FROM public.user_profiles up WHERE up.id = (SELECT auth.uid()) AND up.role = 'admin' AND COALESCE(up.is_active, true) = true)) WITH CHECK (EXISTS (SELECT 1 FROM public.user_profiles up WHERE up.id = (SELECT auth.uid()) AND up.role = 'admin' AND COALESCE(up.is_active, true) = true));
ALTER POLICY user_profiles_self_read ON public.user_profiles USING ((id = (SELECT auth.uid())) OR is_admin());
